        int e = 0;
        int s0 = 0;
        int s1 = 0;
        int s2 = 0;
        int s3 = 0;
        int s4 = 0;
        int kind = 0;
        int status = 0;
        int consumed = 0;
        int got = 0;
        int slen = 0;
        int exact = 0;
        while (pos < n) {
            line += 1;
            e = ItNl(f, pos);
            if ((pos < e) && (emon.Port.BlobU8(f, pos) != 35)) {
                rows += 1;
                s0 = ItSemi(f, pos, e);
                s1 = ItSemi(f, s0 + 1, e);
                s2 = ItSemi(f, s1 + 1, e);
                s3 = ItSemi(f, s2 + 1, e);
                s4 = ItSemi(f, s3 + 1, e);
                kind = emon.Port.BlobU8(f, s0 + 1);
                status = ItDec(f, s1 + 1, s2);
                consumed = ItDec(f, s2 + 1, s3);
                slen = ItHexInto(f, s3 + 1, s4, src);
                emon.Port.CellsDrop(@out, 0);
                if ((kind == 122) || (kind == 90)) {
                    got = Inflate.IzZlib(emon.Testport.CellsBlob(src), 0, slen, @out, st);
                } else {
                    got = Inflate.IzRaw(emon.Testport.CellsBlob(src), 0, slen, @out, st);
                }
                emon.Testport.AssertEqAt(got, status, "status", line);
                if (consumed >= 0) {
                    emon.Testport.AssertEqAt(Inflate.IzConsumed(st), consumed, "consumed", line);
                }
                exact = 0;
                if ((kind == 90) || (kind == 82)) {
                    exact = 1;
                }
                emon.Testport.AssertEqAt(ItCompare(@out, f, s4 + 1, e, exact), -1, "output", line);
                // The Buf form (D492) is held to the Cells one on the same row: status, consumed, every byte.
                emon.Port.BufTruncate(bout, 0);
                if ((kind == 122) || (kind == 90)) {
                    gotb = Inflate.IzZlibBuf(emon.Testport.CellsBlob(src), 0, slen, bout, st2);
                } else {
                    gotb = Inflate.IzRawBuf(emon.Testport.CellsBlob(src), 0, slen, bout, st2);
                }
                emon.Testport.AssertEqAt(gotb, got, "buf status", line);
                emon.Testport.AssertEqAt(Inflate.IzConsumed(st), Inflate.IzConsumed(st2), "buf consumed", line);
                emon.Testport.AssertEqAt(emon.Port.BufLen(bout), emon.Port.CellsLen(@out), "buf length", line);
                k = 0;
                while (k < emon.Port.CellsLen(@out)) {
                    if (emon.Port.BufAt(bout, k) != emon.Port.CellsAt(@out, k)) {
                        emon.Testport.AssertEqAt(emon.Port.BufAt(bout, k), emon.Port.CellsAt(@out, k), "buf byte", line);
                    }
                    k += 1;
                }
            }
            pos = e + 1;
